// A minimal SAML service provider with @node-saml/node-saml (pure JS, no xmlsec1), trimmed from the proof
const { SAML } = require("@node-saml/node-saml");
const SP = "http://127.0.0.1:18082";
const saml = new SAML({
  callbackUrl: SP + "/saml/acs",                       // our ACS
  entryPoint: "http://127.0.0.1:18080/realms/learn/protocol/saml",   // the IdP's SSO URL
  issuer: SP + "/saml/metadata",                       // our entityID (Keycloak: the client id must equal it)
  idpCert: fs.readFileSync(process.env.IDP_CERT_PEM, "utf8"),          // from the IdP descriptor
  audience: SP + "/saml/metadata",                     // the assertion's <Audience> must be us
  wantAssertionsSigned: true, wantAuthnResponseSigned: true,
  identifierFormat: "urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress",
  acceptedClockSkewMs: 5000,
  validateInResponseTo: "always",                      // a response must answer one of our requests, once
});
app.get("/saml/metadata", (req, res) => res.type("application/xml").send(saml.generateServiceProviderMetadata(null, null)));
app.get("/login", async (req, res) => res.redirect(await saml.getAuthorizeUrlAsync("relay-123", undefined, {})));
app.post("/saml/acs", async (req, res) => {
  try { const { profile } = await saml.validatePostResponseAsync(req.body);
        res.json({ ok: true, nameID: profile.nameID, email: profile.email, groups: profile.groups }); }
  catch (e) { res.status(400).json({ ok: false, error: String(e.message || e) }); }   // 'InResponseTo is not valid', 'Invalid document signature'
});
